mapper.select:
select id, order_no, request_no, product_id, product_quantity, warehouse_id, retry_count, fail_reason, next_retry_time, fail_stage, need_manual_intervention, status, is_del, create_time, update_time
from production_order
where is_del = 0

    and status = #{status}


    and product_id = #{productId}


    and warehouse_id = #{warehouseId}

order by id desc
limit #{offset}, #{pageSize}

select count(1)
from production_order
where is_del = 0

    and status = #{status}


    and product_id = #{productId}


    and warehouse_id = #{warehouseId}

select id, order_no, request_no, product_id, product_quantity, warehouse_id, retry_count, fail_reason, next_retry_time, fail_stage, need_manual_intervention, status, is_del, create_time, update_time
from production_order
where status = #{status}
and is_del = 0
order by id asc
limit #{limit}
